INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2450, 'enterprise value', '/ˈentərpraɪz ˈvæljuː/', 'noun', '{"zh-TW":["企業價值"],"en":["the total value of a company including equity and net debt"]}', NULL, 'calculate enterprise value / enterprise value multiple', '[{"en":"The enterprise value of the target company was estimated at $2 billion.","zh-TW":"目標公司的企業價值估計為20億元。"},{"en":"Enterprise value is used in M&A to price takeover bids.","zh-TW":"企業價值用於併購中的收購出價定價。"}]', '{"abbreviation":"EV"}', NULL, 5, 2450, NULL),
(2451, 'entertainment', '/ˌɛntərˈteɪnmənt/', 'noun', '{"zh-TW":["娛樂"],"en":["activities for enjoyment"]}', NULL, 'entertainment industry / live entertainment', '[{"en":"The hotel offers nightly entertainment.","zh-TW":"飯店每晚提供娛樂節目。"},{"en":"The entertainment industry is growing.","zh-TW":"娛樂產業正在成長。"}]', '{"verb":"entertain","noun2":"entertainer","adjective":"entertaining"}', NULL, 5, 2451, NULL),
(2452, 'enthusiastic', '/ɪnˌθjuːziˈæstɪk/', 'adjective', '{"zh-TW":["熱情的；熱心的"],"en":["showing intense enjoyment or interest"]}', '{"prefix":{"text":"en-","meaning":"in (在內)"},"root":{"text":"thusi","meaning":"god (神)"},"suffix":{"text":"-astic","meaning":"relating to (相關的)"},"logic":"如同有神靈附體般的熱情。"}', 'enthusiastic about / enthusiastic response', '[{"en":"She is enthusiastic about her new job.","zh-TW":"她對新工作充滿熱情。"},{"en":"The audience gave an enthusiastic response.","zh-TW":"觀眾給予熱烈回應。"}]', '{"noun":"enthusiasm","adverb":"enthusiastically"}', NULL, 4, 2452, NULL),
(2453, 'entire', '/ɪnˈtaɪər/', 'adjective', '{"zh-TW":["整個的；全部的"],"en":["whole; complete","with no part left out; whole"]}', '{"prefix":{"text":"in-","meaning":"not (不)"},"root":{"text":"tire","meaning":"touch/diminish (觸及/削減)"},"logic":"未被削減的，即「完整的」。"}', 'the entire team/process; the entire team / the entire day / in its entirety', '[{"en":"The entire team was present at the meeting.","zh-TW":"整個團隊都出席了會議。"},{"en":"She spent the entire day on the report.","zh-TW":"她花了一整天在報告上。"},{"en":"The entire team worked overtime.","zh-TW":"整個團隊加班工作。"},{"en":"She read the entire book in one day.","zh-TW":"她一天內讀完了整本書。"}]', '{"adjective":"entire","adverb":"entirely","noun":"entirety"}', NULL, 2, 2453, 115),
(2454, 'entitle', '/ɪnˈtaɪtəl/', 'verb', '{"zh-TW":["賦予權利；命名"],"en":["to give someone the right to do something"]}', NULL, 'be entitled to', '[{"en":"Full-time staff are entitled to 20 days of leave.","zh-TW":"全職員工有權享有20天假期。"},{"en":"The book is entitled ''Modern Management''.","zh-TW":"這本書名為《現代管理》。"}]', '{"noun":"entitlement","verb":"entitle","adjective":"entitled"}', NULL, 3, 2454, NULL),
(2455, 'entitlement', '/ɪnˈtaɪtəlmənt/', 'noun', '{"zh-TW":["權利；應得福利"],"en":["a benefit that an employee has a right to receive"]}', NULL, 'leave entitlement / statutory entitlement / entitlement to benefits', '[{"en":"All employees have a minimum leave entitlement of 14 days.","zh-TW":"所有員工享有最低14天的假期權利。"},{"en":"She checked her entitlement to overtime pay.","zh-TW":"她查詢了她的加班費權利。"}]', '{"verb":"entitle","adjective":"entitled"}', NULL, 4, 2455, 559),
(2456, 'entree', '/ˈɒntreɪ/', 'noun', '{"zh-TW":["主菜"],"en":["the main dish of a meal"]}', NULL, 'entree selection / order an entree', '[{"en":"The entree includes a choice of fish or beef.","zh-TW":"主菜包含魚或牛肉的選擇。"},{"en":"Each entree is served with seasonal vegetables.","zh-TW":"每道主菜配有時令蔬菜。"}]', NULL, NULL, 2, 2456, NULL),
(2457, 'entrepreneur', '/ˌɑːntrəprəˈnɜːr/', 'noun', '{"zh-TW":["企業家；創業者"],"en":["a person who starts and runs a business"]}', NULL, 'successful entrepreneur', '[{"en":"She is a successful entrepreneur in tech.","zh-TW":"她是科技領域的成功企業家。"},{"en":"Entrepreneurs drive innovation.","zh-TW":"企業家推動創新。"}]', '{"noun":"entrepreneur/entrepreneurship","adjective":"entrepreneurial"}', NULL, 4, 2457, NULL),
(2458, 'enumerate', '/ɪˈnjuːməreɪt/', 'verb', '{"zh-TW":["列舉；逐一說明"],"en":["to list or count things individually"]}', NULL, 'enumerate the benefits / enumerate responsibilities', '[{"en":"The contract enumerates all deliverables and payment milestones.","zh-TW":"合約列舉了所有交付成果和付款里程碑。"},{"en":"Please enumerate the risks identified in the assessment.","zh-TW":"請列舉評估中識別的風險。"}]', '{"noun":"enumeration","adjective":"enumerated"}', NULL, 3, 2458, 679),
(2459, 'environment', '/ɪnˈvaɪrənmənt/', 'noun', '{"zh-TW":["環境"],"en":["the natural world; surrounding conditions"]}', NULL, 'work/business environment', '[{"en":"We must protect the environment.","zh-TW":"我們必須保護環境。"},{"en":"A positive work environment boosts morale.","zh-TW":"積極的工作環境提升士氣。"}]', '{"noun":"environment/environmentalist","adjective":"environmental","adverb":"environmentally"}', NULL, 4, 2459, 350),
(2460, 'environmental awareness', '/ɪnˌvaɪrənˈmɛntəl əˈwɛənɪs/', 'noun', '{"zh-TW":["環保意識"],"en":["knowledge and concern about environmental issues"]}', NULL, 'raise environmental awareness / environmental awareness campaign', '[{"en":"The school launched a campaign to raise environmental awareness.","zh-TW":"學校發起了一場提升環保意識的活動。"},{"en":"Environmental awareness drives consumer demand for green products.","zh-TW":"環保意識推動消費者對綠色產品的需求。"}]', NULL, NULL, 5, 2460, NULL),
(2461, 'environmental compliance', '/ɪnˌvaɪrənˈmentəl kəmˈplaɪəns/', 'noun', '{"zh-TW":["環境合規"],"en":["adherence to environmental laws, regulations, and standards"]}', NULL, 'ensure environmental compliance / environmental compliance audit', '[{"en":"The plant was fined for failing to meet environmental compliance standards.","zh-TW":"該工廠因未能達到環境合規標準而被罰款。"},{"en":"Regular audits are conducted to verify environmental compliance.","zh-TW":"定期審計用於驗證環境合規性。"}]', NULL, NULL, 5, 2461, NULL),
(2462, 'environmental governance', '/ɪnˌvaɪrənˈmentəl ˈɡʌvənəns/', 'noun', '{"zh-TW":["環境治理"],"en":["the processes and institutions for making and enforcing environmental decisions"]}', NULL, 'strengthen environmental governance / effective environmental governance / environmental governance framework', '[{"en":"Weak environmental governance allows industries to pollute without penalty.","zh-TW":"薄弱的環境治理允許工業在無懲罰的情況下污染。"},{"en":"Good environmental governance requires participation from communities and NGOs.","zh-TW":"良好的環境治理需要社區和非政府組織的參與。"}]', NULL, NULL, 5, 2462, NULL),
(2463, 'environmental impact', '/ɪnˌvaɪrənˈmɛntəl ˈɪmpækt/', 'noun', '{"zh-TW":["環境影響"],"en":["the effect of an activity on the natural environment"]}', NULL, 'assess environmental impact / reduce environmental impact', '[{"en":"Companies must assess the environmental impact of their operations.","zh-TW":"企業必須評估其運營的環境影響。"},{"en":"The construction project''s environmental impact was carefully reviewed.","zh-TW":"建設項目的環境影響受到了仔細審查。"}]', '{"adjective":"environmental","adverb":"environmentally"}', NULL, 5, 2463, NULL),
(2464, 'environmental impact assessment', '/ɪnˌvaɪrənˈmentəl ˈɪmpækt əˈsesmənt/', 'noun', '{"zh-TW":["環境影響評估"],"en":["a process to evaluate the environmental effects of a proposed project"]}', NULL, 'conduct an environmental impact assessment / environmental impact assessment results', '[{"en":"An environmental impact assessment was required before the factory was approved.","zh-TW":"在工廠獲批前需要進行環境影響評估。"},{"en":"The environmental impact assessment identified risks to local water resources.","zh-TW":"環境影響評估確定了對當地水資源的風險。"}]', '{"abbreviation":"EIA"}', NULL, 5, 2464, NULL),
(2465, 'environmental stewardship', '/''ɪnˌvaɪərənˌmentəl ˌstjuːərdˌʃɪp/', 'noun', '{"zh-TW":["環境管理責任；環境守護"],"en":["the responsible management and protection of the natural environment"]}', NULL, 'practice environmental stewardship / corporate environmental stewardship / environmental stewardship program', '[{"en":"Environmental stewardship requires businesses to consider the ecological impact of their operations.","zh-TW":"環境管理責任要求企業考慮其運營的生態影響。"},{"en":"The national park service is committed to environmental stewardship for future generations.","zh-TW":"國家公園服務致力於為後代承擔環境管理責任。"}]', '{"noun":"stewardship","noun2":"steward"}', NULL, 5, 2465, NULL),
(2466, 'epidemiology', '/ˌepɪˌdiːmiˈɒlədʒi/', 'noun', '{"zh-TW":["流行病學"],"en":["the study of how diseases spread and can be controlled in populations"]}', NULL, 'epidemiology study / molecular epidemiology / applied epidemiology', '[{"en":"Epidemiology identifies risk factors and helps design prevention strategies.","zh-TW":"流行病學識別風險因素並幫助設計預防策略。"},{"en":"Contact tracing is a key epidemiology tool in controlling outbreaks.","zh-TW":"接觸追蹤是控制疫情爆發的關鍵流行病學工具。"}]', '{"adjective":"epidemiological","adverb":"epidemiologically"}', NULL, 4, 2466, NULL),
(2467, 'epistemic', '/ˌepɪˈstiːmɪk/', 'adjective', '{"zh-TW":["認識論的；知識的"],"en":["relating to knowledge or the degree of its validation"]}', NULL, 'epistemic uncertainty / epistemic framework / epistemic value', '[{"en":"The study raises epistemic questions about measurement reliability.","zh-TW":"該研究提出了有關測量可靠性的認識論問題。"},{"en":"Epistemic humility is a virtue in academic research.","zh-TW":"認識謙遜是學術研究的一種美德。"}]', '{"noun":"epistemology","adverb":"epistemically"}', NULL, 3, 2467, NULL),
(2468, 'epistemic injustice', '/ɪˌpɪstəmɪk ɪnˈdʒʌstɪs/', 'noun', '{"zh-TW":["認識論不正義"],"en":["unfairness related to knowledge practices, such as dismissing someone as untrustworthy"]}', NULL, 'testimonial epistemic injustice / hermeneutical epistemic injustice / address epistemic injustice', '[{"en":"Epistemic injustice occurs when a speaker''s knowledge is unfairly dismissed.","zh-TW":"當說話者的知識被不公平地拒絕時，認識論不正義就會發生。"},{"en":"The concept of epistemic injustice helps analyze power dynamics in knowledge production.","zh-TW":"認識論不正義的概念有助於分析知識生產中的權力動態。"}]', '{"adjective":"epistemically unjust"}', NULL, 5, 2468, NULL),
(2469, 'epistemology', '/ɪˌpɪstəˈmɒlədʒi/', 'noun', '{"zh-TW":["認識論；知識論"],"en":["the branch of philosophy concerned with how knowledge is acquired"]}', NULL, 'philosophical epistemology / research epistemology / epistemology of science', '[{"en":"Epistemology asks how we can know what we claim to know.","zh-TW":"認識論探討我們如何能知道我們所宣稱知道的事。"},{"en":"Different epistemologies produce different research designs.","zh-TW":"不同的認識論產生不同的研究設計。"}]', '{"adjective":"epistemological","adverb":"epistemologically"}', NULL, 4, 2469, NULL),
(2470, 'equal', '/ˈiːkwəl/', 'adjective / verb', '{"zh-TW":["相等的；等於"],"en":["the same in quantity, size, or value"]}', NULL, 'equal opportunity/rights', '[{"en":"All employees should receive equal pay for equal work.","zh-TW":"所有員工同工應同酬。"},{"en":"The total equals $5,000.","zh-TW":"總計等於5000美元。"}]', '{"noun":"equality","verb":"equal","adjective":"equal","adverb":"equally"}', NULL, 2, 2470, NULL),
(2471, 'equal opportunity', '/ˌiːkwəl ˌɒpəˈtjuːnɪti/', 'noun', '{"zh-TW":["機會平等"],"en":["the principle that all people should have the same rights and chances"]}', NULL, 'equal opportunity employer / promote equal opportunity', '[{"en":"The company is committed to being an equal opportunity employer.","zh-TW":"公司致力於成為機會平等的雇主。"},{"en":"Equal opportunity policies promote diversity in the workplace.","zh-TW":"機會平等政策促進了職場多樣性。"}]', NULL, NULL, 5, 2471, NULL),
(2472, 'equilibrium price', '/ˌiːkwɪˈlɪbriəm praɪs/', 'noun', '{"zh-TW":["均衡價格"],"en":["the price at which the quantity supplied equals the quantity demanded in a market"]}', NULL, 'reach equilibrium price / equilibrium price determination / market equilibrium price', '[{"en":"At the equilibrium price, there is no tendency for the price to rise or fall.","zh-TW":"在均衡價格時，價格沒有上漲或下跌的趨勢。"},{"en":"A surplus or shortage will push the market toward its equilibrium price over time.","zh-TW":"供過於求或供不應求將隨時間推移推動市場趨向均衡價格。"}]', NULL, NULL, 5, 2472, NULL),
(2473, 'equip', '/ɪˈkwɪp/', 'verb', '{"zh-TW":["裝備；配備"],"en":["to provide with necessary items or skills"]}', NULL, 'well-equipped / equip with', '[{"en":"The office is equipped with modern technology.","zh-TW":"辦公室配備了現代技術。"},{"en":"Training equips employees with new skills.","zh-TW":"培訓為員工配備新技能。"}]', '{"noun":"equipment","verb":"equip","adjective":"equipped"}', NULL, 2, 2473, 680),
(2474, 'equipment', 'ɪˈkwɪpmənt', 'noun', '{"zh-TW":["設備；器材","裝備"],"en":["tools or machines needed","items supplied for a purpose"]}', NULL, 'office equipment/safety equipment', '[{"en":"All equipment must be properly maintained.","zh-TW":"所有設備必須妥善維護。"}]', '{"verb":"equip","adjective":"equipped"}', NULL, 3, 2474, 28),
(2475, 'equitable', '/ˈekwɪtəbəl/', 'adjective', '{"zh-TW":["公平的；公正的"],"en":["fair and impartial; dealing fairly with all concerned"]}', NULL, 'equitable distribution / equitable treatment / equitable solution', '[{"en":"An equitable distribution of resources reduces social inequality.","zh-TW":"公平分配資源可以減少社會不平等。"},{"en":"The mediator proposed an equitable solution acceptable to both parties.","zh-TW":"調解員提出了一個雙方都能接受的公平解決方案。"}]', '{"adverb":"equitably","noun":"equity"}', NULL, 3, 2475, NULL),
(2476, 'equity', '/ˈɛkwɪti/', 'noun', '{"zh-TW":["股權；權益"],"en":["the value of shares in a company","fairness"]}', NULL, 'private equity / home equity', '[{"en":"They raised capital through private equity.","zh-TW":"他們透過私募股權募集資金。"},{"en":"The company has strong brand equity.","zh-TW":"公司擁有強大的品牌價值。"}]', '{"noun":"equity","adjective":"equitable"}', NULL, 2, 2476, 351),
(2477, 'equity capital', '/ˈekwɪti ˈkæpɪtl/', 'noun', '{"zh-TW":["股本；權益資本"],"en":["funds raised through issuing shares rather than borrowing"]}', NULL, 'raise equity capital / equity capital base', '[{"en":"The company strengthened its equity capital base through a rights issue.","zh-TW":"公司通過配股增強了其股本基礎。"},{"en":"Equity capital does not require repayment but dilutes existing shareholders.","zh-TW":"股本不需要償還，但會稀釋現有股東的股份。"}]', NULL, NULL, 5, 2477, NULL),
(2478, 'equity carve-out', '/ˈekwɪti kɑːrv aʊt/', 'noun', '{"zh-TW":["股權分拆"],"en":["a partial IPO in which a parent company offers shares in a subsidiary"]}', NULL, 'conduct an equity carve-out / equity carve-out transaction / partial carve-out', '[{"en":"The conglomerate pursued an equity carve-out to unlock value in its tech division.","zh-TW":"該集團通過股權分拆來釋放其科技部門的價值。"},{"en":"An equity carve-out raises cash while allowing the parent to retain control.","zh-TW":"股權分拆籌集資金同時允許母公司保持控制。"}]', NULL, NULL, 5, 2478, NULL),
(2479, 'equity dilution', '/ˈekwɪti daɪˈluːʃən/', 'noun', '{"zh-TW":["股權稀釋"],"en":["reduction in existing shareholders percentage due to issuing new shares"]}', NULL, 'avoid equity dilution / equity dilution risk', '[{"en":"A large funding round caused significant equity dilution for founders.","zh-TW":"大規模融資輪次對創辦人造成了顯著的股權稀釋。"},{"en":"Anti-dilution provisions protect investors from equity dilution.","zh-TW":"反稀釋條款保護投資者免受股權稀釋影響。"}]', NULL, NULL, 5, 2479, NULL),
(2480, 'equity financing', '/ˈekwɪti ˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["股權融資"],"en":["raising capital by issuing shares of stock to investors"]}', NULL, 'pursue equity financing / equity financing round / equity financing vs debt financing', '[{"en":"The company opted for equity financing to avoid increasing its debt.","zh-TW":"公司選擇股權融資以避免增加債務。"},{"en":"Equity financing dilutes existing shareholders'' ownership stake.","zh-TW":"股權融資稀釋了現有股東的持股比例。"}]', NULL, NULL, 5, 2480, NULL),
(2481, 'equity grant', '/ˈekwɪti ɡrɑːnt/', 'noun', '{"zh-TW":["股權授予"],"en":["shares or stock options awarded to employees as part of compensation"]}', NULL, 'equity grant schedule / equity grant vesting / receive an equity grant', '[{"en":"The equity grant vests over four years with a one-year cliff.","zh-TW":"股權授予在四年內歸屬，並有一年的懸崖期。"},{"en":"Equity grants align employee interests with company performance.","zh-TW":"股權授予使員工利益與公司績效保持一致。"}]', NULL, NULL, 4, 2481, NULL),
(2482, 'equity issuance', '/ˈekwɪti ɪˈʃuːəns/', 'noun', '{"zh-TW":["股票發行"],"en":["the process of creating and selling new shares to raise capital"]}', NULL, 'complete an equity issuance / equity issuance costs', '[{"en":"The equity issuance raised $30 million to fund expansion.","zh-TW":"股票發行籌集了3000萬元用於擴張。"},{"en":"Equity issuance dilutes existing shareholders but avoids adding debt.","zh-TW":"股票發行稀釋了現有股東，但避免了增加債務。"}]', NULL, NULL, 5, 2482, NULL),
(2483, 'equity premium', '/ˈekwɪti ˈpriːmiəm/', 'noun', '{"zh-TW":["股票風險溢價"],"en":["the extra return that investors expect from stocks over risk-free assets"]}', NULL, 'equity risk premium / historical equity premium / equity premium puzzle', '[{"en":"The equity premium compensates investors for bearing stock market risk.","zh-TW":"股票風險溢價補償投資者承擔股票市場風險。"},{"en":"Estimating the equity premium is central to asset pricing models.","zh-TW":"估計股票風險溢價是資產定價模型的核心。"}]', NULL, NULL, 5, 2483, NULL),
(2484, 'equity release', '/ˈekwɪti rɪˈliːs/', 'noun', '{"zh-TW":["房產淨值釋出"],"en":["accessing the value built up in property as tax-free cash"]}', NULL, 'equity release scheme / apply for equity release', '[{"en":"Equity release allowed the retiree to fund home improvements.","zh-TW":"房產淨值釋出使退休人士能夠為家居改善提供資金。"},{"en":"Equity release products are subject to strict regulation.","zh-TW":"房產淨值釋出產品受到嚴格監管。"}]', NULL, NULL, 5, 2484, NULL),
(2485, 'equity stake', '/ˈekwɪti steɪk/', 'noun', '{"zh-TW":["股權份額"],"en":["a percentage ownership interest in a company"]}', NULL, 'acquire an equity stake / equity stake of 20% / sell equity stake', '[{"en":"The investor acquired a 15% equity stake in the startup.","zh-TW":"投資者收購了新創公司15%的股權份額。"},{"en":"She negotiated an equity stake as part of her executive compensation.","zh-TW":"她在高管薪酬談判中爭取到了股權份額。"}]', NULL, NULL, 4, 2485, NULL),
(2486, 'equity-backed', '/ˈekwɪti bækt/', 'adjective', '{"zh-TW":["股權支持的"],"en":["financed or secured by equity"]}', NULL, 'equity-backed funding / equity-backed project / equity-backed venture', '[{"en":"The startup secured equity-backed financing to expand operations.","zh-TW":"這家初創公司獲得了股權支持的融資以擴大業務。"},{"en":"Equity-backed deals align investor and management interests.","zh-TW":"股權支持的交易使投資者和管理層的利益一致。"}]', NULL, NULL, 5, 2486, NULL),
(2487, 'equivalent', '/ɪˈkwɪvələnt/', 'adjective / noun', '{"zh-TW":["等同的；等價物","等同的；等價的"],"en":["equal in value, function, or meaning"]}', '{"prefix":{"text":"equi-","meaning":"equal (等同)"},"root":{"text":"val","meaning":"worth (價值)"},"suffix":{"text":"-ent","meaning":"being (…的)"},"logic":"價值等同的。"}', 'equivalent to; equivalent to / the equivalent of / roughly equivalent', '[{"en":"One mile is equivalent to 1.6 kilometers.","zh-TW":"一英里等於1.6公里。"},{"en":"There is no equivalent product on the market.","zh-TW":"市場上沒有同等的產品。"},{"en":"One mile is roughly equivalent to 1.6 kilometers.","zh-TW":"一英里大約等於1.6公里。"},{"en":"There is no equivalent word in English.","zh-TW":"英語中沒有等同的字。"}]', '{"noun":"equivalent/equivalence","adjective":"equivalent"}', NULL, 4, 2487, 868),
(2488, 'equivocate', '/''ɪˌkwɪvəˌkeɪt/', 'verb', '{"zh-TW":["含糊其詞；說模稜兩可的話"],"en":["to use ambiguous language so as to conceal the truth or avoid committing oneself"]}', NULL, 'equivocate on / equivocate about / refuse to equivocate', '[{"en":"Politicians often equivocate when asked about controversial policy decisions.","zh-TW":"當被問及有爭議的政策決定時，政治家往往含糊其詞。"},{"en":"She refused to equivocate and gave a direct and honest answer.","zh-TW":"她拒絕含糊其詞，給出了直接而誠實的回答。"}]', '{"noun":"equivocation","adjective":"equivocal","adverb":"equivocally"}', NULL, 4, 2488, NULL),
(2489, 'ergonomics', '/ˌɜːrɡəˈnɒmɪks/', 'noun', '{"zh-TW":["人體工學；人因工程"],"en":["the science of designing workplaces to fit the user"]}', NULL, 'improve ergonomics / ergonomics assessment', '[{"en":"Good ergonomics reduces the risk of repetitive strain injuries.","zh-TW":"良好的人體工學設計降低了重複性損傷的風險。"},{"en":"The company conducted an ergonomics assessment for all workstations.","zh-TW":"公司對所有工作站進行了人體工學評估。"}]', '{"adjective":"ergonomic","adverb":"ergonomically"}', NULL, 4, 2489, NULL),
(2490, 'erode', '/ɪˈroʊd/', 'verb', '{"zh-TW":["侵蝕；削弱"],"en":["to gradually wear away or diminish"]}', NULL, 'erode confidence/trust', '[{"en":"Competition has eroded profit margins.","zh-TW":"競爭侵蝕了利潤率。"},{"en":"Public trust in the brand has eroded.","zh-TW":"公眾對品牌的信任已被削弱。"}]', '{"noun":"erosion","verb":"erode"}', NULL, 2, 2490, NULL),
(2491, 'erosion', '/ɪˈroʊʒn/', 'noun', '{"zh-TW":["侵蝕"],"en":["the gradual wearing away of soil or rock"]}', '{"prefix":{"text":"e-","meaning":"away (離去)"},"root":{"text":"ros","meaning":"gnaw (啃蝕)"},"suffix":{"text":"-ion","meaning":"process (過程)"},"logic":"被啃蝕掉的過程，即「侵蝕」。"}', 'soil erosion / coastal erosion', '[{"en":"Soil erosion is a serious environmental problem.","zh-TW":"土壤侵蝕是嚴重的環境問題。"},{"en":"Heavy rain accelerates erosion.","zh-TW":"大雨加速侵蝕。"}]', '{"verb":"erode"}', NULL, 3, 2491, NULL),
(2492, 'ERP', '/ˌiː ɑːr ˈpiː/', 'noun', '{"zh-TW":["企業資源規劃系統"],"en":["enterprise resource planning; integrated software for managing business processes"]}', NULL, 'implement an ERP / ERP system / ERP software / ERP upgrade', '[{"en":"The company implemented a new ERP to unify its global operations.","zh-TW":"公司實施了新的企業資源規劃系統以統一其全球業務。"},{"en":"ERP integration reduced manual data entry errors significantly.","zh-TW":"ERP整合顯著減少了手動數據輸入錯誤。"}]', '{"full form":"enterprise resource planning"}', NULL, 1, 2492, NULL),
(2493, 'erratic', '/''ɪˈrætɪk/', 'adjective', '{"zh-TW":["不穩定的；難以預測的"],"en":["not even or regular in pattern or movement; unpredictable"]}', NULL, 'erratic behavior / erratic performance / erratic market', '[{"en":"Erratic weather patterns are making agricultural planning more difficult.","zh-TW":"不穩定的天氣模式使農業規劃更加困難。"},{"en":"The stock''s erratic price movement made investors nervous.","zh-TW":"股票價格的不穩定波動讓投資者感到不安。"}]', '{"adverb":"erratically","noun":"erraticism"}', NULL, 3, 2493, NULL),
(2494, 'error', '/ˈerər/', 'noun', '{"zh-TW":["錯誤；失誤"],"en":["a mistake; something incorrectly done"]}', NULL, 'human/clerical error', '[{"en":"The report contained several errors.","zh-TW":"報告中有幾處錯誤。"},{"en":"The error was caused by a software bug.","zh-TW":"錯誤是由軟體缺陷造成的。"}]', '{"noun":"error","adjective":"erroneous"}', NULL, 2, 2494, NULL),
(2495, 'error and omission', '/ˈerər ænd əˈmɪʃən/', 'noun', '{"zh-TW":["錯誤與遺漏"],"en":["a type of liability insurance protecting against claims of inadequate work or negligent actions"]}', NULL, 'errors and omissions insurance / errors and omissions claim', '[{"en":"The consultant took out errors and omissions insurance before providing advice.","zh-TW":"顧問在提供建議之前購買了錯誤與遺漏保險。"},{"en":"An errors and omissions claim can arise from mistakes in professional reports.","zh-TW":"專業報告中的錯誤可能引發錯誤與遺漏索賠。"}]', '{"abbreviation":"E&O","synonym":"professional indemnity insurance"}', NULL, 5, 2495, NULL),
(2496, 'erudite', '/ˈerjʊdaɪt/', 'adjective', '{"zh-TW":["博學的；有學問的"],"en":["having or showing great knowledge or learning"]}', NULL, 'erudite scholar / erudite discussion / erudite commentary', '[{"en":"Her erudite commentary impressed the entire review panel.","zh-TW":"她博學的評論給整個評審小組留下了深刻印象。"},{"en":"The professor''s erudite lectures attracted students from many fields.","zh-TW":"教授博學的講座吸引了來自許多領域的學生。"}]', '{"noun":"erudition","adverb":"eruditely"}', NULL, 3, 2496, NULL),
(2497, 'escalate', '/ˈeskəleɪt/', 'verb', '{"zh-TW":["上報；升級"],"en":["to refer an issue to a higher authority or increase intensity"]}', NULL, 'escalate a complaint / escalate to management / escalate an issue', '[{"en":"She escalated the unresolved complaint to her supervisor.","zh-TW":"她將未解決的投訴上報給主管。"},{"en":"If a solution cannot be found, escalate the issue immediately.","zh-TW":"如果找不到解決方案，立即上報問題。"}]', '{"noun":"escalation","adjective":"escalated"}', NULL, 3, 2497, 681),
(2498, 'escalate costs', '/ˈeskəleɪt kɒsts/', 'verb', '{"zh-TW":["成本上升；費用升高"],"en":["to increase in costs over time, often unexpectedly"]}', NULL, 'escalating project costs / escalating operational costs', '[{"en":"Project costs escalated due to scope changes and material shortages.","zh-TW":"由於範圍變更和材料短缺，項目成本上升了。"},{"en":"The company took steps to prevent escalating labor costs.","zh-TW":"公司採取措施防止勞動力成本升高。"}]', NULL, NULL, 5, 2498, NULL),
(2499, 'escalation', '/ˌeskəˈleɪʃən/', 'noun', '{"zh-TW":["升級；上報"],"en":["raising an issue to a higher authority when it cannot be resolved at the current level"]}', NULL, 'escalation process / escalate an issue / escalation path', '[{"en":"The customer complaint required escalation to the director.","zh-TW":"客戶投訴需要上報給總監。"},{"en":"Clear escalation paths reduce delays in problem resolution.","zh-TW":"清晰的升級路徑減少了問題解決的延誤。"}]', '{"verb":"escalate","adjective":"escalated"}', NULL, 4, 2499, 784);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2500, 'escalation matrix', '/ˌeskəˈleɪʃən ˈmeɪtrɪks/', 'noun', '{"zh-TW":["升級矩陣"],"en":["a document defining when and how issues should be escalated to higher management"]}', NULL, 'use the escalation matrix / refer to the escalation matrix', '[{"en":"The escalation matrix defines who to contact for different severity levels.","zh-TW":"升級矩陣定義了針對不同嚴重程度應聯繫誰。"},{"en":"Following the escalation matrix ensures issues are resolved efficiently.","zh-TW":"遵循升級矩陣確保問題得到高效解決。"}]', NULL, NULL, 5, 2500, NULL),
(2501, 'escalation path', '/ˌeskəˈleɪʃən pɑːθ/', 'noun', '{"zh-TW":["升級路徑"],"en":["a defined process for routing unresolved issues to higher authority"]}', NULL, 'define escalation paths / follow the escalation path', '[{"en":"The escalation path ensures urgent issues reach managers quickly.","zh-TW":"升級路徑確保緊急問題迅速觸及管理者。"},{"en":"Clear escalation paths reduce customer wait times.","zh-TW":"清晰的升級路徑減少了客戶等待時間。"}]', NULL, NULL, 5, 2501, NULL),
(2502, 'escalation procedure', '/ˌeskəˈleɪʃən prəˈsiːdʒər/', 'noun', '{"zh-TW":["升級程序"],"en":["the defined steps for raising unresolved issues to higher management levels"]}', NULL, 'follow the escalation procedure / escalation procedure policy', '[{"en":"The escalation procedure ensures critical issues reach senior management.","zh-TW":"升級程序確保重大問題能夠達到高層管理人員。"},{"en":"All customer complaints must follow the escalation procedure.","zh-TW":"所有客戶投訴必須遵循升級程序。"}]', NULL, NULL, 5, 2502, NULL),
(2503, 'escape', '/ɪˈskeɪp/', 'verb', '{"zh-TW":["逃脫；避免"],"en":["to get free from","to avoid something unpleasant"]}', NULL, 'escape route / narrow escape', '[{"en":"Know the escape routes in case of fire.","zh-TW":"了解火災時的逃生路線。"},{"en":"We had a narrow escape from the flooding.","zh-TW":"我們險些遭遇洪水。"}]', '{"verb":"escape","noun":"escape"}', NULL, 2, 2503, NULL),
(2504, 'escrow', '/ˈeskroʊ/', 'noun', '{"zh-TW":["第三方託管；代管"],"en":["a financial arrangement where a third party holds assets until conditions are met"]}', NULL, 'hold in escrow / escrow account / place funds in escrow / release from escrow', '[{"en":"Funds were placed in escrow pending completion of the sale.","zh-TW":"資金被放入第三方託管，等待銷售完成。"},{"en":"The escrow agent released payment once all conditions were satisfied.","zh-TW":"所有條件滿足後，代管代理人釋放了付款。"}]', '{"verb":"escrow"}', NULL, 2, 2504, NULL),
(2505, 'escrow account', '/ˈeskroʊ əˈkaʊnt/', 'noun', '{"zh-TW":["托管帳戶"],"en":["a third-party account holding funds until specified conditions are met"]}', NULL, 'hold funds in escrow / open an escrow account', '[{"en":"The purchase price was placed in an escrow account pending due diligence.","zh-TW":"購買價款存放在托管帳戶中，等待完成盡職調查。"},{"en":"An escrow account protects both buyer and seller during a property transaction.","zh-TW":"托管帳戶在房產交易中保護買方和賣方雙方。"}]', NULL, NULL, 5, 2505, NULL),
(2506, 'escrow agent', '/ˈeskroʊ ˈeɪdʒənt/', 'noun', '{"zh-TW":["託管代理人"],"en":["a neutral third party holding funds or documents until conditions are met"]}', NULL, 'appoint an escrow agent / escrow agent fee', '[{"en":"The escrow agent released the funds after the contract conditions were satisfied.","zh-TW":"在合約條件得到滿足後，託管代理人釋放了資金。"},{"en":"An escrow agent provides security to both buyer and seller in a transaction.","zh-TW":"託管代理人在交易中為買賣雙方提供保障。"}]', NULL, NULL, 4, 2506, NULL),
(2507, 'ESOP', '/ˈiːsɒp/', 'noun', '{"zh-TW":["員工持股計劃"],"en":["employee stock ownership plan; a benefit giving employees company shares"]}', NULL, 'set up an ESOP / ESOP contribution / ESOP plan', '[{"en":"The ESOP aligned employees'' interests with the company''s success.","zh-TW":"員工持股計劃使員工利益與公司成功保持一致。"},{"en":"Many tech firms use ESOPs as a long-term retention tool.","zh-TW":"許多科技公司使用員工持股計劃作為長期留才工具。"}]', '{"full form":"employee stock ownership plan"}', NULL, 1, 2507, NULL),
(2508, 'espresso', '/ɪˈsprɛsəʊ/', 'noun', '{"zh-TW":["義式濃縮咖啡"],"en":["a strong coffee made by forcing steam through ground coffee"]}', NULL, 'double espresso / espresso shot', '[{"en":"She ordered a double espresso to start her morning.","zh-TW":"她點了一杯雙份義式濃縮咖啡開始她的早晨。"},{"en":"Espresso is the base for many coffee drinks.","zh-TW":"義式濃縮咖啡是許多咖啡飲品的基底。"}]', NULL, NULL, 3, 2508, NULL),
(2509, 'essential', '/ɪˈsenʃəl/', 'adjective', '{"zh-TW":["必要的；基本的","必要的；本質的"],"en":["absolutely necessary; extremely important"]}', '{"root":{"text":"essent","meaning":"being/existence (存在)"},"suffix":{"text":"-ial","meaning":"relating to (相關的)"},"logic":"與存在本質相關的（不可缺少的）。"}', 'essential for/to; essential skills / essential information / absolutely essential', '[{"en":"Communication skills are essential for this role.","zh-TW":"溝通技能對這個職位是必要的。"},{"en":"It is essential to meet the deadline.","zh-TW":"在截止日期前完成是必要的。"},{"en":"Water is essential for life.","zh-TW":"水是生命所必需的。"},{"en":"Good communication skills are essential for this job.","zh-TW":"良好的溝通能力對這份工作至關重要。"}]', '{"noun":"essential/essentials","adjective":"essential","adverb":"essentially"}', NULL, 3, 2509, 869),
(2510, 'essentialism', '/ɪˈsenʃəlɪzəm/', 'noun', '{"zh-TW":["本質主義"],"en":["the view that entities have inherent essential properties"]}', NULL, 'strategic essentialism / cultural essentialism / critique essentialism', '[{"en":"Critics argue that essentialism reinforces stereotypes about gender and culture.","zh-TW":"批評者認為本質主義強化了關於性別和文化的刻板印象。"},{"en":"Essentialism assumes fixed identities that postmodern theory challenges.","zh-TW":"本質主義假設後現代理論所挑戰的固定身份。"}]', '{"adjective":"essentialist"}', NULL, 4, 2510, NULL),
(2511, 'establish', '/ɪˈstæblɪʃ/', 'verb', '{"zh-TW":["建立；確立","建立；設立"],"en":["to set up; to prove or show","to set up on a firm or permanent basis"]}', '{"prefix":{"text":"e-","meaning":"out (完全)"},"root":{"text":"stabl","meaning":"stable (穩定)"},"suffix":{"text":"-ish","meaning":"make (使)"},"logic":"使其穩固確立，即「建立」。"}', 'establish a company/reputation; establish a company / well-established', '[{"en":"The company was established in 1990.","zh-TW":"公司成立於1990年。"},{"en":"We need to establish clear guidelines.","zh-TW":"我們需要建立明確的指導方針。"},{"en":"They established a new policy for remote work.","zh-TW":"他們制定了新的遠端工作政策。"}]', '{"noun":"establishment","verb":"establish","adjective":"established"}', NULL, 3, 2511, 116),
(2512, 'estate agent', '/''ɪˌsteɪt ˌeɪdʒənt/', 'noun', '{"zh-TW":["房地產中介；物業代理"],"en":["a person or business that arranges the selling, renting, or management of properties"]}', NULL, 'contact an estate agent / trusted estate agent / estate agent fee', '[{"en":"We visited three estate agents before finding a suitable rental apartment.","zh-TW":"我們拜訪了三家房地產中介，才找到一套合適的出租公寓。"},{"en":"The estate agent arranged viewings for six properties in one afternoon.","zh-TW":"房地產中介在一個下午安排了六套房產的看房。"}]', NULL, NULL, 4, 2512, NULL),
(2513, 'estate planning', '/ɪˈsteɪt ˈplænɪŋ/', 'noun', '{"zh-TW":["遺產規劃"],"en":["arranging for the transfer of assets after death to minimize taxes and disputes"]}', NULL, 'engage in estate planning / estate planning services', '[{"en":"Estate planning ensures assets are distributed according to your wishes.","zh-TW":"遺產規劃確保資產按照您的意願分配。"},{"en":"The wealth manager provided comprehensive estate planning services.","zh-TW":"財富管理者提供了全面的遺產規劃服務。"}]', NULL, NULL, 5, 2513, NULL),
(2514, 'estimate', '/ˈestɪmeɪt/', 'verb / noun', '{"zh-TW":["估計；預算","估計"],"en":["to roughly calculate; an approximate judgment","to roughly calculate or judge the value of"]}', '{"root":{"text":"estim","meaning":"value (評價)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"做出評價，即「估計」。"}', 'rough/conservative estimate; rough estimate / cost estimate / estimate the cost', '[{"en":"We estimate the cost at $50,000.","zh-TW":"我們估計成本為5萬美元。"},{"en":"The initial estimate was too low.","zh-TW":"最初的估計太低了。"},{"en":"We estimate the project will cost $2 million.","zh-TW":"我們估計這個專案將花費200萬美元。"},{"en":"Can you give me a rough estimate?","zh-TW":"你能給我一個粗略的估計嗎？"}]', '{"noun":"estimate/estimation","verb":"estimate","adjective":"estimated","noun2":"estimation"}', NULL, 3, 2514, 29),
(2515, 'estimated time of arrival', '/ˈɛstɪmɪtɪd taɪm əv əˈraɪvəl/', 'noun', '{"zh-TW":["預計到達時間"],"en":["the projected time when something will arrive"]}', NULL, 'check estimated time of arrival / estimated time of arrival alert', '[{"en":"The estimated time of arrival for the shipment is Friday.","zh-TW":"貨物的預計到達時間是週五。"},{"en":"Track your order to see the estimated time of arrival.","zh-TW":"追蹤您的訂單以查看預計到達時間。"}]', '{"abbreviation":"ETA"}', NULL, 5, 2515, NULL),
(2516, 'estimated useful life', '/ˈestɪmeɪtɪd ˈjuːsfəl laɪf/', 'noun', '{"zh-TW":["估計使用年限"],"en":["the projected period over which an asset is expected to be used productively"]}', NULL, 'determine estimated useful life / revise estimated useful life', '[{"en":"The estimated useful life of the equipment is 10 years.","zh-TW":"設備的估計使用年限為10年。"},{"en":"Depreciation is calculated based on the estimated useful life of each asset.","zh-TW":"折舊根據每項資產的估計使用年限計算。"}]', NULL, NULL, 5, 2516, NULL),
(2517, 'estimation', 'ˌɛstɪˈmeɪʃən', 'noun', '{"zh-TW":["估算；估計","評價"],"en":["a calculated guess","a judgment of value"]}', NULL, 'cost estimation/time estimation', '[{"en":"Please prepare an accurate cost estimation.","zh-TW":"請準備準確的成本估算。"}]', '{"verb":"estimate","adjective":"estimated"}', NULL, 4, 2517, 785),
(2518, 'estoppel', '/ɪˈstɒpəl/', 'noun', '{"zh-TW":["禁止反言"],"en":["a legal principle preventing someone from contradicting a prior statement"]}', NULL, 'promissory estoppel / doctrine of estoppel / equitable estoppel', '[{"en":"The doctrine of estoppel prevented the company from denying the promise.","zh-TW":"禁止反言原則阻止公司否認承諾。"},{"en":"Promissory estoppel can make an otherwise unenforceable promise binding.","zh-TW":"約因禁止反言可以使原本無法執行的承諾具有約束力。"}]', NULL, NULL, 3, 2518, NULL),
(2519, 'ethics code', '/ˈeθɪks koʊd/', 'noun', '{"zh-TW":["道德準則；倫理守則"],"en":["a set of rules defining ethical standards for members of an organization"]}', NULL, 'adopt an ethics code / sign the ethics code', '[{"en":"All staff are required to sign the ethics code annually.","zh-TW":"所有員工每年必須簽署道德準則。"},{"en":"The ethics code prohibits accepting gifts from suppliers.","zh-TW":"道德準則禁止接受供應商的禮物。"}]', NULL, NULL, 4, 2519, NULL),
(2520, 'ethnocentrism', '/ˌeθnəʊˈsentrɪzəm/', 'noun', '{"zh-TW":["民族中心主義"],"en":["judging other cultures by the standards of your own"]}', NULL, 'overcome ethnocentrism / ethnocentrism in research / avoid ethnocentrism', '[{"en":"Ethnocentrism distorts cross-cultural research and policy analysis.","zh-TW":"民族中心主義扭曲了跨文化研究和政策分析。"},{"en":"Anthropologists must guard against ethnocentrism when studying other societies.","zh-TW":"人類學家在研究其他社會時必須防範民族中心主義。"}]', '{"adjective":"ethnocentric","adverb":"ethnocentrically"}', NULL, 5, 2520, NULL),
(2521, 'ethnography', '/eθˈnɒɡrəfi/', 'noun', '{"zh-TW":["民族誌；人種誌"],"en":["the systematic study of people and cultures"]}', NULL, 'conduct ethnography / ethnography research / ethnographic study', '[{"en":"The researcher conducted ethnography among urban communities.","zh-TW":"研究員對城市社區進行了民族誌研究。"},{"en":"Ethnography requires extended fieldwork and observation.","zh-TW":"民族誌研究需要長期的田野調查和觀察。"}]', '{"adjective":"ethnographic","adverb":"ethnographically"}', NULL, 4, 2521, NULL),
(2522, 'etiology', '/ˌiːtiˈɒlədʒi/', 'noun', '{"zh-TW":["病因學；病因"],"en":["the cause or causes of a disease or condition"]}', NULL, 'unknown etiology / viral etiology / etiology of a disease', '[{"en":"The etiology of the condition remains unclear despite extensive research.","zh-TW":"儘管進行了廣泛研究，該病的病因仍不清楚。"},{"en":"Understanding the etiology of a disease is essential for effective treatment.","zh-TW":"了解疾病的病因對有效治療至關重要。"}]', '{"adjective":"etiological"}', NULL, 3, 2522, NULL),
(2523, 'euphemism', '/''juːfəmɪzəm/', 'noun', '{"zh-TW":["委婉語；婉辭"],"en":["a mild or indirect word or expression substituted for one that might be considered too harsh or blunt"]}', NULL, 'use a euphemism / common euphemism / polite euphemism', '[{"en":"Saying ''passed away'' is a common euphemism for ''died.''","zh-TW":"說「過世了」是「死了」的常用委婉說法。"},{"en":"Corporate language is full of euphemisms like ''downsizing'' instead of ''firing.''","zh-TW":"企業語言充滿了委婉語，比如用「裁員」代替「解雇」。"}]', '{"adjective":"euphemistic"}', NULL, 3, 2523, NULL),
(2524, 'eutrophication', '/juːˌtrɒfɪˈkeɪʃən/', 'noun', '{"zh-TW":["優養化；水體富營養化"],"en":["excessive richness of nutrients in water, causing algal blooms"]}', NULL, 'prevent eutrophication / eutrophication of lakes / control eutrophication', '[{"en":"Agricultural runoff contributes to eutrophication of rivers and lakes.","zh-TW":"農業逕流造成河流和湖泊的優養化。"},{"en":"Eutrophication depletes oxygen in water, killing fish and other aquatic life.","zh-TW":"優養化消耗水中的氧氣，殺死魚類和其他水生生物。"}]', '{"verb":"eutrophy","adjective":"eutrophic"}', NULL, 5, 2524, NULL),
(2525, 'evaluate', '/ɪˈvæljueɪt/', 'verb', '{"zh-TW":["評估；評價","評估"],"en":["to judge the value or quality of","to judge or determine the significance or value of"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"valu","meaning":"value (價值)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"衡量出價值來，即「評估」。"}', 'evaluate performance/options; evaluate performance / evaluate options', '[{"en":"We need to evaluate all options carefully.","zh-TW":"我們需要仔細評估所有選項。"},{"en":"Employee performance is evaluated annually.","zh-TW":"員工績效每年評估一次。"},{"en":"Teachers evaluate student performance regularly.","zh-TW":"老師定期評估學生表現。"},{"en":"We need to evaluate all the options.","zh-TW":"我們需要評估所有選項。"}]', '{"noun":"evaluation","verb":"evaluate"}', NULL, 3, 2525, 30),
(2526, 'evaluate performance', '/ɪˈvæljueɪt pəˈfɔːrməns/', 'verb', '{"zh-TW":["評估績效"],"en":["to systematically assess how well something or someone is performing"]}', NULL, 'evaluate employee performance / evaluate project performance', '[{"en":"Managers evaluate performance using a set of measurable criteria.","zh-TW":"管理者使用一套可衡量的標準評估績效。"},{"en":"The project was evaluated for performance against the original budget.","zh-TW":"項目按照原始預算評估了其績效。"}]', NULL, NULL, 5, 2526, NULL),
(2527, 'evaluation', 'ɪˌvæljʊˈeɪʃən', 'noun', '{"zh-TW":["評估；評價","考核"],"en":["the process of assessing","a judgment of value"]}', NULL, 'performance evaluation/project evaluation', '[{"en":"The evaluation report was submitted.","zh-TW":"評估報告已提交。"}]', '{"verb":"evaluate","adjective":"evaluative"}', NULL, 4, 2527, 561),
(2528, 'evaluation criteria', '/ɪˌvæljuˈeɪʃən kraɪˈtɪəriə/', 'noun', '{"zh-TW":["評估標準"],"en":["the standards and factors used to assess and select between options or proposals"]}', NULL, 'define evaluation criteria / meet evaluation criteria', '[{"en":"The tender documents listed price, quality, and experience as evaluation criteria.","zh-TW":"招標文件將價格、質量和經驗列為評估標準。"},{"en":"Clear evaluation criteria reduce subjectivity in supplier selection.","zh-TW":"清晰的評估標準減少了供應商選擇中的主觀性。"}]', NULL, NULL, 5, 2528, NULL),
(2529, 'evaluative', '/ɪˈvæljʊətɪv/', 'adjective', '{"zh-TW":["評估性的；判斷性的"],"en":["relating to making judgments or evaluations"]}', NULL, 'evaluative framework / evaluative criteria / evaluative approach', '[{"en":"The study uses an evaluative framework to assess program effectiveness.","zh-TW":"研究使用評估框架評估計畫效果。"},{"en":"Evaluative criteria must be established before data collection begins.","zh-TW":"評估標準必須在數據收集開始之前建立。"}]', '{"verb":"evaluate","noun":"evaluation"}', NULL, 4, 2529, NULL),
(2530, 'even', '/ˈiːvən/', 'verb, adjective, adverb', '{"zh-TW":["【主要意義-副詞/連接詞】甚至；連……也","【次要意義-動詞】使平整；使相等；使均衡","【次要意義-形容詞】平穩的；均等的；偶數的"],"en":["[primary] used to emphasize something unexpected","[secondary - verb] to make flat, level, or equal","[secondary - adjective] equal, level, or divisible by two"]}', NULL, 'even out / even up / even the score / on an even keel', '[{"en":"The extra payment will even out the discrepancy in the accounts.","zh-TW":"額外付款將消除帳目中的差異。"},{"en":"They worked to even the playing field for smaller companies.","zh-TW":"他們努力為小公司創造公平競爭的環境。"},{"en":"Production levels have evened out after the initial surge.","zh-TW":"初期激增後，生產水平已趨於平穩。"}]', '{"adverb":"evenly","noun":"evenness"}', '動詞 even out/up 意為「使平衡/消除差異」，常見於 TOEIC 財務或生產排程的語境，與副詞「甚至」的用法完全不同。', 1, 2530, NULL),
(2531, 'evening', '/ˈiːvnɪŋ/', 'noun', '{"zh-TW":["傍晚；晚上"],"en":["the part of the day between afternoon and night"]}', NULL, 'good evening / evening shift', '[{"en":"Good evening, everyone.","zh-TW":"大家晚上好。"},{"en":"She works the evening shift.","zh-TW":"她上晚班。"}]', '{"noun":"evening"}', NULL, 3, 2531, NULL),
(2532, 'event', 'ɪˈvɛnt', 'noun', '{"zh-TW":["事件；活動","賽事"],"en":["a thing that happens","a planned occasion"]}', NULL, 'corporate event/upcoming event', '[{"en":"The annual event is scheduled for May.","zh-TW":"年度活動定於五月舉行。"}]', '{"adjective":"eventful","adverb":"eventfully"}', NULL, 2, 2532, NULL),
(2533, 'event coordinator', '/ɪˈvɛnt kəʊˈɔːrdɪneɪtər/', 'noun', '{"zh-TW":["活動協調員"],"en":["a person responsible for planning and managing events"]}', NULL, 'hire an event coordinator / experienced event coordinator', '[{"en":"The event coordinator handled all logistics for the conference.","zh-TW":"活動協調員處理了會議的所有後勤工作。"},{"en":"A good event coordinator anticipates problems before they arise.","zh-TW":"優秀的活動協調員在問題出現之前預先考慮到。"}]', NULL, NULL, 5, 2533, NULL),
(2534, 'event planning', '/ɪˈvɛnt ˈplænɪŋ/', 'noun', '{"zh-TW":["活動策劃"],"en":["the process of organizing events from concept to execution"]}', NULL, 'event planning skills / professional event planning', '[{"en":"She works in event planning for corporate conferences.","zh-TW":"她從事企業會議的活動策劃工作。"},{"en":"Good event planning requires attention to detail and flexibility.","zh-TW":"良好的活動策劃需要關注細節和靈活性。"}]', '{"verb":"plan","noun":"event planner"}', NULL, 5, 2534, NULL),
(2535, 'event risk', '/ɪˈvent rɪsk/', 'noun', '{"zh-TW":["事件風險"],"en":["the risk of loss resulting from a sudden unexpected event affecting an investment"]}', NULL, 'mitigate event risk / event risk premium', '[{"en":"Political instability increased event risk in the emerging market portfolio.","zh-TW":"政治不穩定增加了新興市場投資組合中的事件風險。"},{"en":"Credit downgrades often reflect event risks not anticipated at issuance.","zh-TW":"信用降級通常反映了發行時未預期的事件風險。"}]', NULL, NULL, 4, 2535, NULL),
(2536, 'event-driven', '/ɪˈvent ˈdrɪvən/', 'adjective', '{"zh-TW":["事件驅動的"],"en":["relating to an architecture where actions are triggered by events"]}', NULL, 'event-driven architecture / event-driven programming / event-driven system', '[{"en":"Event-driven architecture enables loosely coupled, scalable systems.","zh-TW":"事件驅動架構支持鬆耦合、可擴展的系統。"},{"en":"Modern UIs rely on event-driven programming to handle user interactions.","zh-TW":"現代用戶界面依靠事件驅動程式設計來處理用戶交互。"}]', NULL, NULL, 4, 2536, NULL),
(2537, 'eventually', '/ɪˈventʃuəli/', 'adverb', '{"zh-TW":["最終；終於"],"en":["in the end; after a period of time"]}', NULL, 'eventually lead to', '[{"en":"The negotiations eventually led to an agreement.","zh-TW":"談判最終達成了協議。"},{"en":"He eventually became the CEO.","zh-TW":"他最終成為了執行長。"}]', '{"adjective":"eventual","adverb":"eventually"}', NULL, 4, 2537, NULL),
(2538, 'eviction notice', '/''ɪˌvɪkʃən ˌnəʊtɪs/', 'noun', '{"zh-TW":["驅逐通知；逐屋通知"],"en":["a formal legal document issued to a tenant requiring them to vacate the property by a certain date"]}', NULL, 'receive an eviction notice / issue an eviction notice / contest an eviction notice', '[{"en":"The tenant received an eviction notice after failing to pay rent for three months.","zh-TW":"房客在三個月未付租金後收到了驅逐通知。"},{"en":"She sought legal advice on how to contest the eviction notice she had received.","zh-TW":"她尋求法律建議，了解如何對她收到的驅逐通知提出異議。"}]', '{"verb":"evict","noun":"eviction"}', NULL, 5, 2538, NULL),
(2539, 'evidence', '/ˈevɪdəns/', 'noun', '{"zh-TW":["證據；跡象","證據"],"en":["facts or signs showing something is true","facts or information indicating whether something is true"]}', '{"prefix":{"text":"e-","meaning":"out (出)"},"root":{"text":"vid","meaning":"see (看)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"看得出來的事實，即「證據」。"}', 'provide/present evidence; scientific evidence / evidence suggests / lack of evidence', '[{"en":"There is evidence of improvement in sales.","zh-TW":"有銷售改善的證據。"},{"en":"The data provides evidence of a trend.","zh-TW":"數據提供了趨勢的證據。"},{"en":"There is no evidence to support this claim.","zh-TW":"沒有證據支持這項說法。"},{"en":"The evidence suggests a link between the two.","zh-TW":"證據顯示兩者之間有關聯。"}]', '{"noun":"evidence","adjective":"evident","adverb":"evidently"}', NULL, 3, 2539, 562),
(2540, 'evidence-based', '/ˈevɪdəns beɪst/', 'adjective', '{"zh-TW":["實證的；循證的"],"en":["based on evidence from research rather than intuition or tradition"]}', NULL, 'evidence-based practice / evidence-based policy / evidence-based medicine', '[{"en":"Evidence-based medicine relies on clinical trials rather than anecdotal reports.","zh-TW":"循證醫學依賴臨床試驗而非個案報告。"},{"en":"Evidence-based policy design improves the effectiveness of public programs.","zh-TW":"實證政策設計提高了公共計畫的有效性。"}]', NULL, NULL, 5, 2540, NULL),
(2541, 'evolve', '/ɪˈvɑːlv/', 'verb', '{"zh-TW":["進化；發展"],"en":["to develop gradually over time"]}', NULL, 'evolve into/over time', '[{"en":"The company has evolved into a global brand.","zh-TW":"公司已發展成為全球品牌。"},{"en":"Consumer preferences evolve constantly.","zh-TW":"消費者偏好不斷演變。"}]', '{"noun":"evolution","verb":"evolve"}', NULL, 2, 2541, NULL),
(2542, 'exacerbate', '/ɪɡˈzæsərbeɪt/', 'verb', '{"zh-TW":["加劇；惡化"],"en":["to make a problem or bad situation worse"]}', NULL, 'exacerbate tensions / exacerbate inequality / exacerbate problems', '[{"en":"Inflation exacerbates the financial burden on low-income households.","zh-TW":"通貨膨脹加劇了低收入家庭的財務負擔。"},{"en":"Poor communication can exacerbate conflicts within teams.","zh-TW":"溝通不良會加劇團隊內部的衝突。"}]', '{"noun":"exacerbation"}', NULL, 4, 2542, NULL),
(2543, 'exact', '/ɪɡˈzækt/', 'adjective', '{"zh-TW":["精確的；確切的"],"en":["completely accurate; precise"]}', NULL, 'exact amount/location', '[{"en":"The exact cost has not been determined yet.","zh-TW":"確切費用尚未確定。"},{"en":"Please provide the exact date.","zh-TW":"請提供確切日期。"}]', '{"adjective":"exact","adverb":"exactly"}', NULL, 2, 2543, NULL),
(2544, 'exam', '/ɪɡˈzæm/', 'noun', '{"zh-TW":["考試"],"en":["a formal test of knowledge"]}', NULL, 'take an exam / pass an exam', '[{"en":"I have three exams next week.","zh-TW":"我下週有三場考試。"},{"en":"She passed all her exams.","zh-TW":"她通過了所有考試。"}]', '{"noun2":"examination","noun3":"examiner"}', NULL, 1, 2544, NULL),
(2545, 'examination', '/ɪɡˌzæmɪˈneɪʃən/', 'noun', '{"zh-TW":["檢查；診察"],"en":["a formal medical check of someone''s health"]}', NULL, 'physical examination / eye examination', '[{"en":"The doctor performed a thorough physical examination.","zh-TW":"醫生進行了徹底的身體檢查。"},{"en":"An eye examination is recommended every two years.","zh-TW":"建議每兩年進行一次眼科檢查。"}]', '{"verb":"examine","adjective":"examined"}', NULL, 4, 2545, 563),
(2546, 'examine', '/ɪɡˈzæmɪn/', 'verb', '{"zh-TW":["檢查；審查"],"en":["to inspect closely; to test knowledge"]}', NULL, 'examine closely/carefully', '[{"en":"The auditor examined the financial records.","zh-TW":"審計師審查了財務記錄。"},{"en":"We need to examine this issue more closely.","zh-TW":"我們需要更仔細地審查這個問題。"}]', '{"noun":"examination/examiner","verb":"examine"}', NULL, 3, 2546, 352),
(2547, 'example', '/ɪɡˈzæmpəl/', 'noun', '{"zh-TW":["例子；範例"],"en":["something typical of a group","a model to follow"]}', NULL, 'for example / set an example', '[{"en":"For example, we could reduce costs here.","zh-TW":"例如，我們可以在這裡降低成本。"},{"en":"She sets a good example for new staff.","zh-TW":"她為新員工樹立了好榜樣。"}]', '{"noun":"example","adjective":"exemplary","verb":"exemplify"}', NULL, 3, 2547, NULL),
(2548, 'exceed', '/ɪkˈsiːd/', 'verb', '{"zh-TW":["超過；超出","超過；超越"],"en":["to go beyond a limit or expectation","to go beyond a limit or standard"]}', '{"prefix":{"text":"ex-","meaning":"out (超出)"},"root":{"text":"ceed","meaning":"go (走)"},"logic":"走出去超越界限，即「超過」。"}', 'exceed expectations/limits; exceed expectations / exceed the limit', '[{"en":"Sales exceeded expectations this quarter.","zh-TW":"本季度銷售超出了預期。"},{"en":"Do not exceed the speed limit.","zh-TW":"不要超過速限。"},{"en":"Sales exceeded our expectations.","zh-TW":"銷售額超出了我們的預期。"}]', '{"adjective":"exceeding","adverb":"exceedingly"}', NULL, 2, 2548, 117),
(2549, 'excellent', '/ˈeksələnt/', 'adjective', '{"zh-TW":["優秀的；極好的"],"en":["extremely good; outstanding"]}', NULL, 'excellent performance/service', '[{"en":"She received excellent feedback from clients.","zh-TW":"她收到了客戶的優秀評價。"},{"en":"The hotel provides excellent service.","zh-TW":"這家飯店提供優質服務。"}]', '{"noun":"excellence","adjective":"excellent"}', NULL, 3, 2549, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2550, 'exception', '/ɪkˈsepʃən/', 'noun', '{"zh-TW":["例外"],"en":["something that does not follow a rule"]}', NULL, 'with the exception of / make an exception', '[{"en":"All staff must attend, with no exceptions.","zh-TW":"所有員工必須參加，沒有例外。"},{"en":"We can make an exception in this case.","zh-TW":"在這種情況下我們可以破例。"}]', '{"noun":"exception","adjective":"exceptional","adverb":"exceptionally"}', NULL, 3, 2550, NULL),
(2551, 'excess', '/ɪkˈses/', 'noun / adjective', '{"zh-TW":["過量；多餘的"],"en":["more than necessary or permitted"]}', NULL, 'in excess of / excess baggage', '[{"en":"Costs were in excess of the budget.","zh-TW":"費用超過了預算。"},{"en":"Excess inventory should be sold at a discount.","zh-TW":"多餘的庫存應打折出售。"}]', '{"noun":"excess","adjective":"excessive","adverb":"excessively"}', NULL, 2, 2551, NULL),
(2552, 'excess inventory', '/ɪkˈses ɪnˈventɔːri/', 'noun', '{"zh-TW":["過剩庫存；滯銷庫存"],"en":["stock that exceeds current or projected demand"]}', NULL, 'reduce excess inventory / clear excess inventory', '[{"en":"Excess inventory was sold at a discount to free up warehouse space.","zh-TW":"過剩庫存以折扣出售，以釋放倉庫空間。"},{"en":"Better demand forecasting helped reduce excess inventory by 40%.","zh-TW":"更好的需求預測有助於將過剩庫存減少40%。"}]', NULL, NULL, 5, 2552, NULL),
(2553, 'exchange', '/ɪksˈtʃeɪndʒ/', 'noun / verb', '{"zh-TW":["交換；兌換"],"en":["to give and receive; a place for trading","to give something and receive something in return"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"change","meaning":"change (改變)"},"logic":"把東西拿出來改變，即「交換」。"}', 'exchange rate / in exchange for; exchange rate / exchange information', '[{"en":"What is today''s exchange rate?","zh-TW":"今天的匯率是多少？"},{"en":"They exchanged business cards at the conference.","zh-TW":"他們在會議上交換了名片。"},{"en":"Can I exchange this shirt for a larger size?","zh-TW":"我可以把這件襯衫換大一號嗎？"},{"en":"They exchanged contact information.","zh-TW":"他們交換了聯絡資訊。"}]', '{"noun":"exchange","verb":"exchange","adjective":"exchangeable"}', NULL, 3, 2553, NULL),
(2554, 'exchange booth', '/''ɪkstʃeɪndʒ buːθ/', 'noun', '{"zh-TW":["外幣兌換亭；貨幣兌換處"],"en":["a small kiosk or counter where currencies are exchanged"]}', NULL, 'find an exchange booth / airport exchange booth / convenient exchange booth', '[{"en":"There is an exchange booth at the airport arrivals hall.","zh-TW":"機場入境大廳有一個外幣兌換亭。"},{"en":"Exchange booths at tourist areas often offer less favorable rates than banks.","zh-TW":"旅遊區的外幣兌換亭通常提供比銀行不太優惠的匯率。"}]', NULL, NULL, 5, 2554, NULL),
(2555, 'exchange controls', '/ɪksˈtʃeɪndʒ kənˈtroʊlz/', 'noun', '{"zh-TW":["外匯管制"],"en":["government restrictions on the purchase or sale of foreign currencies"]}', NULL, 'impose exchange controls / relax exchange controls', '[{"en":"Exchange controls limited the company''s ability to repatriate profits.","zh-TW":"外匯管制限制了公司匯回利潤的能力。"},{"en":"Some developing countries impose exchange controls to protect their currency.","zh-TW":"一些發展中國家實施外匯管制以保護其貨幣。"}]', NULL, NULL, 5, 2555, NULL),
(2556, 'exchange policy', '/ɪksˈtʃeɪndʒ ˈpɒlɪsi/', 'noun', '{"zh-TW":["換貨政策"],"en":["the rules governing the exchange of purchased items"]}', NULL, 'flexible exchange policy / review the exchange policy', '[{"en":"The store has a 30-day exchange policy.","zh-TW":"這家商店有30天的換貨政策。"},{"en":"Please read the exchange policy before making your purchase.","zh-TW":"購買前請閱讀換貨政策。"}]', NULL, NULL, 5, 2556, NULL),
(2557, 'exchange rate', '/ɪksˈtʃeɪndʒ reɪt/', 'noun', '{"zh-TW":["匯率"],"en":["the value of one currency compared to another"]}', NULL, 'favorable exchange rate / exchange rate fluctuation', '[{"en":"The exchange rate affected the cost of our overseas purchase.","zh-TW":"匯率影響了我們的海外採購成本。"},{"en":"Monitor exchange rate fluctuations before converting money.","zh-TW":"在換錢前監測匯率波動。"}]', NULL, NULL, 5, 2557, NULL),
(2558, 'exchange rate risk', '/ɪksˈtʃeɪndʒ reɪt rɪsk/', 'noun', '{"zh-TW":["匯率風險"],"en":["the risk that changes in currency values will affect business outcomes"]}', NULL, 'manage exchange rate risk / hedge exchange rate risk', '[{"en":"The importer hedged exchange rate risk using forward contracts.","zh-TW":"進口商使用遠期合約對沖了匯率風險。"},{"en":"Exchange rate risk is particularly relevant in cross-border transactions.","zh-TW":"匯率風險在跨境交易中尤為相關。"}]', NULL, NULL, 5, 2558, NULL),
(2559, 'exchange student', '/ɪksˈtʃeɪndʒ ˈstjuːdənt/', 'noun', '{"zh-TW":["交換學生"],"en":["a student who studies temporarily at another institution abroad"]}', NULL, 'host an exchange student / exchange student program', '[{"en":"She participated as an exchange student in Germany.","zh-TW":"她以交換學生的身份在德國學習。"},{"en":"Exchange student programs promote cultural understanding.","zh-TW":"交換學生計劃促進了文化理解。"}]', NULL, NULL, 5, 2559, NULL),
(2560, 'exchange-traded fund', '/ɪksˈtʃeɪndʒ ˈtreɪdɪd fʌnd/', 'noun', '{"zh-TW":["交易所買賣基金"],"en":["an investment fund traded on a stock exchange like a regular share"]}', NULL, 'invest in an ETF / ETF performance', '[{"en":"ETFs offer low-cost exposure to diversified portfolios.","zh-TW":"交易所買賣基金提供低成本的多元化投資組合敞口。"},{"en":"She shifted from actively managed funds to ETFs to reduce fees.","zh-TW":"她從主動管理基金轉向了交易所買賣基金以降低費用。"}]', '{"abbreviation":"ETF"}', NULL, 5, 2560, NULL),
(2561, 'excise duty', '/ˈeksaɪz ˈdjuːti/', 'noun', '{"zh-TW":["消費稅；貨物稅"],"en":["a tax levied on specific goods such as alcohol, tobacco, or fuel"]}', NULL, 'pay excise duty / excise duty rate', '[{"en":"Excise duty on alcohol was increased in the annual budget.","zh-TW":"消費稅在年度預算中提高了對酒精的稅率。"},{"en":"Importers must pay excise duty before goods are released from customs.","zh-TW":"進口商必須在貨物從海關放行前繳納消費稅。"}]', NULL, NULL, 4, 2561, NULL),
(2562, 'excited', '/ɪkˈsaɪtɪd/', 'adjective', '{"zh-TW":["興奮的；激動的"],"en":["feeling great enthusiasm"]}', NULL, 'get excited / excited about', '[{"en":"We are excited about the new product launch.","zh-TW":"我們對新產品上市感到興奮。"},{"en":"The team is excited to start.","zh-TW":"團隊很期待開始。"}]', '{"adjective":"excited","verb":"excite","noun":"excitement","adjective2":"exciting"}', NULL, 3, 2562, NULL),
(2563, 'exciting', 'ɪkˈsaɪtɪŋ', 'adjective', '{"zh-TW":["令人興奮的；刺激的","有趣的"],"en":["causing enthusiasm","stimulating"]}', NULL, 'exciting opportunity/exciting news', '[{"en":"This is an exciting opportunity for the company.","zh-TW":"這是公司的一個令人興奮的機會。"}]', '{"verb":"excite","noun":"excitement","adverb":"excitingly"}', NULL, 3, 2563, NULL),
(2564, 'exclude', '/ɪkˈskluːd/', 'verb', '{"zh-TW":["排除；排斥"],"en":["to prevent from being included"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"clude","meaning":"close (關閉)"},"logic":"關在外面，即「排除」。"}', 'exclude from; exclude from / exclude the possibility', '[{"en":"Tax is excluded from the listed price.","zh-TW":"標示價格不含稅。"},{"en":"Some items are excluded from the warranty.","zh-TW":"某些物品不在保固範圍內。"},{"en":"The price excludes tax and delivery.","zh-TW":"價格不含稅和運費。"},{"en":"Don''t exclude anyone from the discussion.","zh-TW":"不要把任何人排除在討論之外。"}]', '{"noun":"exclusion","verb":"exclude","adjective":"exclusive"}', NULL, 3, 2564, NULL),
(2565, 'exclusion clause', '/ɪkˈskluːʒən klɔːz/', 'noun', '{"zh-TW":["免責條款；排除條款"],"en":["a contract term that limits or excludes liability for certain events"]}', NULL, 'include an exclusion clause / rely on the exclusion clause', '[{"en":"The exclusion clause exempted the company from liability for force majeure.","zh-TW":"免責條款使公司免於對不可抗力事件承擔責任。"},{"en":"The exclusion clause was challenged and found to be unenforceable.","zh-TW":"免責條款受到質疑，被認定為不可執行。"}]', NULL, NULL, 5, 2565, NULL),
(2566, 'exclusive', '/ɪkˈskluːsɪv/', 'adjective', '{"zh-TW":["獨家的；專屬的"],"en":["limited to one person or group; high-end"]}', NULL, 'exclusive deal/rights', '[{"en":"We signed an exclusive distribution agreement.","zh-TW":"我們簽署了獨家經銷協議。"},{"en":"The hotel caters to an exclusive clientele.","zh-TW":"這家飯店專門服務高端客戶。"}]', '{"noun":"exclusivity","adjective":"exclusive","adverb":"exclusively"}', NULL, 3, 2566, 353),
(2567, 'exclusive distribution', '/ɪkˈskluːsɪv ˌdɪstrɪˈbjuːʃən/', 'noun', '{"zh-TW":["獨家分銷"],"en":["an arrangement where only one distributor is authorized to sell in a territory"]}', NULL, 'grant exclusive distribution rights / exclusive distribution agreement', '[{"en":"An exclusive distribution deal was signed for the Asia-Pacific region.","zh-TW":"簽署了亞太地區的獨家分銷協議。"},{"en":"Exclusive distribution limits competition but requires strong marketing efforts.","zh-TW":"獨家分銷限制了競爭，但需要強有力的行銷工作。"}]', NULL, NULL, 5, 2567, NULL),
(2568, 'exclusive rights', '/ɪkˈskluːsɪv raɪts/', 'noun', '{"zh-TW":["獨家權利"],"en":["the sole authorization to use, sell, or distribute something in a specific market"]}', NULL, 'grant exclusive rights / exclusive rights agreement', '[{"en":"The publisher acquired exclusive rights to distribute the series in Asia.","zh-TW":"出版商獲得了在亞洲分銷該系列的獨家權利。"},{"en":"Exclusive rights arrangements restrict competitors from entering the market.","zh-TW":"獨家權利安排限制了競爭對手進入市場。"}]', NULL, NULL, 5, 2568, NULL),
(2569, 'exclusivity clause', '/ɪkˌskluːˈsɪvɪti klɔːz/', 'noun', '{"zh-TW":["獨家條款"],"en":["a contract provision preventing parties from working with competitors"]}', NULL, 'include an exclusivity clause / exclusivity clause period', '[{"en":"The distribution agreement includes a two-year exclusivity clause.","zh-TW":"分銷協議包含兩年的獨家條款。"},{"en":"The exclusivity clause prevented the supplier from selling to rivals.","zh-TW":"獨家條款阻止了供應商向競爭對手出售。"}]', NULL, NULL, 5, 2569, NULL),
(2570, 'exculpatory', '/ɪkˈskʌlpətəri/', 'adjective', '{"zh-TW":["免罪的；開脫的"],"en":["tending to clear someone from fault or guilt"]}', NULL, 'exculpatory evidence / exculpatory clause / exculpatory statement', '[{"en":"The defense attorney found exculpatory evidence that changed the verdict.","zh-TW":"辯護律師找到了改變裁決的免罪證據。"},{"en":"Prosecutors must disclose exculpatory evidence to the defense.","zh-TW":"檢察官必須向辯護方披露免罪證據。"}]', NULL, NULL, 4, 2570, NULL),
(2571, 'excursion', '/ɪkˈskɜːrʒən/', 'noun', '{"zh-TW":["短途旅遊；遠足"],"en":["a short trip made for pleasure"]}', NULL, 'day excursion / optional excursion', '[{"en":"We booked an excursion to the nearby volcano.","zh-TW":"我們預訂了前往附近火山的一日遊。"},{"en":"The cruise offers several excursions at each port.","zh-TW":"郵輪在每個港口提供多種短途遊覽。"}]', NULL, NULL, 3, 2571, NULL),
(2572, 'excursion ticket', '/''ɪkˈskɜːʃən ˌtɪkɪt/', 'noun', '{"zh-TW":["短程旅行票；遊覽票"],"en":["a specially priced ticket for a short journey or trip, often at a reduced fare"]}', NULL, 'buy an excursion ticket / discounted excursion ticket', '[{"en":"She bought an excursion ticket to take a day trip to the countryside.","zh-TW":"她買了一張短程旅行票，前往鄉村進行一日遊。"},{"en":"Excursion tickets are available at reduced prices for group bookings.","zh-TW":"短程旅行票對於團體預訂可享有折扣價格。"}]', NULL, NULL, 5, 2572, NULL),
(2573, 'execute', '/ˈeksɪkjuːt/', 'verb', '{"zh-TW":["執行；實施"],"en":["to carry out a plan or action"]}', NULL, 'execute a plan/strategy', '[{"en":"The team executed the project flawlessly.","zh-TW":"團隊完美地執行了項目。"},{"en":"The strategy was well executed.","zh-TW":"該策略執行得很好。"}]', '{"noun":"execution/executive","verb":"execute"}', NULL, 3, 2573, 354),
(2574, 'executive', '/ɪɡˈzekjʊtɪv/', 'noun', '{"zh-TW":["高管；主管"],"en":["a senior manager with significant decision-making authority"]}', NULL, 'senior executive / top executive / executive team / executive decision', '[{"en":"The executive team approved the new strategic direction.","zh-TW":"高管團隊批准了新的戰略方向。"},{"en":"She joined as a senior executive responsible for global sales.","zh-TW":"她以負責全球銷售的高管身份加入。"}]', '{"plural":"executives","adjective":"executive"}', NULL, 3, 2574, 118),
(2575, 'executive committee', '/ɪɡˈzekjʊtɪv kəˈmɪti/', 'noun', '{"zh-TW":["執行委員會"],"en":["the senior leadership group responsible for running an organization"]}', NULL, 'executive committee meeting / executive committee decision / sit on the executive committee', '[{"en":"The executive committee approved the new acquisition strategy.","zh-TW":"執行委員會批准了新的收購策略。"},{"en":"Major decisions are escalated to the executive committee for approval.","zh-TW":"重大決策被上報執行委員會審批。"}]', '{"abbreviation":"ExCo"}', NULL, 5, 2575, NULL),
(2576, 'executive compensation', '/ɪɡˈzekjʊtɪv ˌkɒmpenˈseɪʃən/', 'noun', '{"zh-TW":["高管薪酬"],"en":["the total pay package provided to senior executives of a company"]}', NULL, 'disclose executive compensation / executive compensation structure', '[{"en":"The executive compensation package included salary, bonus, and stock options.","zh-TW":"高管薪酬方案包括薪資、獎金和股票期權。"},{"en":"Shareholders voted on the executive compensation policy at the annual meeting.","zh-TW":"股東在年會上就高管薪酬政策進行了投票。"}]', NULL, NULL, 5, 2576, NULL),
(2577, 'executive education', '/''ɪɡˌzekjʊtɪv ˌedʒʊˈkeɪʃən/', 'noun', '{"zh-TW":["高管教育；主管培訓"],"en":["educational programs designed for working professionals and corporate executives"]}', NULL, 'enroll in executive education / executive education program / executive education MBA', '[{"en":"She completed an executive education program to prepare for a senior leadership role.","zh-TW":"她完成了一個高管教育計劃，為高級領導職位做準備。"},{"en":"Top business schools offer executive education programs tailored to industry needs.","zh-TW":"頂尖商學院提供針對行業需求量身定制的高管教育計劃。"}]', NULL, NULL, 5, 2577, NULL),
(2578, 'executive lounge', '/ɪɡˈzɛkjʊtɪv laʊndʒ/', 'noun', '{"zh-TW":["行政貴賓室"],"en":["a premium lounge in a hotel for executive floor guests"]}', NULL, 'access the executive lounge / executive lounge benefits', '[{"en":"Executive lounge guests enjoy complimentary snacks and drinks.","zh-TW":"行政貴賓室賓客享有免費零食和飲料。"},{"en":"The executive lounge offers a quiet workspace for business travelers.","zh-TW":"行政貴賓室為商務旅客提供安靜的工作空間。"}]', NULL, NULL, 5, 2578, NULL),
(2579, 'executive summary', '/ɪɡˈzekjʊtɪv ˈsʌməri/', 'noun', '{"zh-TW":["執行摘要"],"en":["a brief overview of a longer document for quick decision-making"]}', NULL, 'prepare an executive summary / executive summary of the report', '[{"en":"The executive summary allowed the board to grasp the key points quickly.","zh-TW":"執行摘要讓董事會快速掌握了要點。"},{"en":"A well-written executive summary is essential for business proposals.","zh-TW":"精心撰寫的執行摘要對商業提案至關重要。"}]', NULL, NULL, 5, 2579, NULL),
(2580, 'exemplar', '/ɪɡˈzemplaːr/', 'noun', '{"zh-TW":["榜樣；典範"],"en":["a person or thing serving as a typical example or excellent model"]}', NULL, 'serve as an exemplar / follow as an exemplar / national exemplar', '[{"en":"She was held up as an exemplar of professional excellence in the field.","zh-TW":"她被譽為該領域職業卓越的典範。"},{"en":"The company''s ethical practices made it an exemplar for others in the industry to follow.","zh-TW":"公司的道德實踐使其成為行業內其他公司效仿的典範。"}]', '{"adjective":"exemplary","verb":"exemplify"}', NULL, 3, 2580, NULL),
(2581, 'exemplify', '/ɪɡˈzemplɪfaɪ/', 'verb', '{"zh-TW":["例示；說明"],"en":["to be a typical example of; to illustrate by example"]}', NULL, 'exemplify best practice / exemplify a concept / exemplify the trend', '[{"en":"This case study exemplifies the challenges of market entry.","zh-TW":"這個案例研究說明了市場進入的挑戰。"},{"en":"The diagram exemplifies how the components interact.","zh-TW":"該圖表說明了各組件如何相互作用。"}]', '{"noun":"exemplification","noun2":"example"}', NULL, 3, 2581, NULL),
(2582, 'exempt', '/ɪɡˈzempt/', 'adjective / verb', '{"zh-TW":["免除的；豁免"],"en":["free from an obligation or liability"]}', NULL, 'exempt from tax/duty', '[{"en":"Non-profit organizations are exempt from taxes.","zh-TW":"非營利組織免稅。"},{"en":"Small businesses may be exempted from the regulation.","zh-TW":"小型企業可能免於遵守該法規。"}]', '{"noun":"exemption","verb":"exempt","adjective":"exempt"}', NULL, 2, 2582, NULL),
(2583, 'exercise', '/ˈeksərsaɪz/', 'noun / verb', '{"zh-TW":["運動；行使"],"en":["physical activity; to use a right or power"]}', NULL, 'exercise caution/authority', '[{"en":"Please exercise caution when handling chemicals.","zh-TW":"處理化學品時請小心謹慎。"},{"en":"Shareholders may exercise their voting rights.","zh-TW":"股東可以行使投票權。"}]', '{"noun":"exercise","verb":"exercise"}', NULL, 3, 2583, NULL),
(2584, 'exhaust', '/ɪɡˈzɔːst/', 'verb / noun', '{"zh-TW":["耗盡；排氣"],"en":["to use up completely; waste gases"]}', NULL, 'exhaust all options/resources', '[{"en":"We have exhausted all possible solutions.","zh-TW":"我們已經用盡了所有可能的解決方案。"},{"en":"Vehicle exhaust contributes to air pollution.","zh-TW":"汽車排氣造成空氣污染。"}]', '{"noun":"exhaustion/exhaust","verb":"exhaust","adjective":"exhausting/exhausted/exhaustive"}', NULL, 3, 2584, NULL),
(2585, 'exhaustive', '/''ɪɡˈzɔːstɪv/', 'adjective', '{"zh-TW":["詳盡的；徹底的"],"en":["including or considering all elements or aspects; fully comprehensive"]}', NULL, 'exhaustive research / exhaustive list / exhaustive testing', '[{"en":"The committee conducted an exhaustive review of all applicants.","zh-TW":"委員會對所有申請人進行了詳盡的審查。"},{"en":"The engineer ran exhaustive tests before the software was released to the public.","zh-TW":"工程師在軟體向公眾發布之前進行了徹底的測試。"}]', '{"adverb":"exhaustively","noun":"exhaustiveness"}', NULL, 4, 2585, NULL),
(2586, 'exhibit', '/ɪɡˈzɪbɪt/', 'verb / noun', '{"zh-TW":["展覽；展示","展覽品；展覽"],"en":["to show publicly; a display","an object displayed in a museum","a public display of art or other items"]}', '{"prefix":{"text":"ex-","meaning":"out (外)"},"root":{"text":"hibit","meaning":"hold (持有)"},"logic":"拿出來展示，即「展覽」。"}', 'exhibit at a trade show; art exhibit / exhibit hall / on exhibit', '[{"en":"The company will exhibit at the trade fair.","zh-TW":"公司將在商展上展覽。"},{"en":"The museum has a new exhibit on technology.","zh-TW":"博物館有一個新的科技展覽。"},{"en":"The museum has a new dinosaur exhibit.","zh-TW":"博物館有新的恐龍展覽。"},{"en":"Her paintings are on exhibit at the gallery.","zh-TW":"她的畫作正在畫廊展出。"}]', '{"noun":"exhibit/exhibition/exhibitor","verb":"exhibit"}', NULL, 3, 2586, 119),
(2587, 'exhibition', '/ˌɛksɪˈbɪʃən/', 'noun', '{"zh-TW":["展覽"],"en":["a public display of art or objects"]}', NULL, 'art exhibition / on exhibition', '[{"en":"The exhibition runs until March.","zh-TW":"展覽持續到三月。"},{"en":"We visited an art exhibition.","zh-TW":"我們參觀了一場藝術展覽。"}]', '{"verb":"exhibit","noun2":"exhibit"}', NULL, 4, 2587, NULL),
(2588, 'exist', '/ɪɡˈzɪst/', 'verb', '{"zh-TW":["存在"],"en":["to be real; to have actual being"]}', NULL, 'already exist / cease to exist', '[{"en":"The problem still exists.","zh-TW":"問題仍然存在。"},{"en":"Does a solution already exist?","zh-TW":"已經有解決方案了嗎？"}]', '{"verb":"exist","noun":"existence","adjective":"existing","adjective2":"existent"}', NULL, 2, 2588, NULL),
(2589, 'exit barrier', '/ˈeksɪt ˈbæriər/', 'noun', '{"zh-TW":["退出壁壘"],"en":["factors that make it difficult for a company to leave a market or industry"]}', NULL, 'face exit barriers / overcome exit barriers', '[{"en":"High exit barriers trapped the company in a loss-making business segment.","zh-TW":"高退出壁壘使公司陷入虧損的業務板塊。"},{"en":"Long-term contracts with suppliers create significant exit barriers.","zh-TW":"與供應商的長期合約創造了顯著的退出壁壘。"}]', '{"opposite":"entry barrier"}', NULL, 4, 2589, NULL),
(2590, 'exit interview', '/ˈeksɪt ˈɪntərvjuː/', 'noun', '{"zh-TW":["離職面談"],"en":["a meeting conducted when an employee leaves to understand their reasons"]}', NULL, 'conduct an exit interview / exit interview questions / post-exit interview', '[{"en":"The exit interview revealed recurring issues with management style.","zh-TW":"離職面談揭示了與管理風格相關的反覆問題。"},{"en":"HR conducts exit interviews to identify areas of improvement.","zh-TW":"人力資源部進行離職面談以識別改進領域。"}]', NULL, NULL, 5, 2590, NULL),
(2591, 'exit multiple', '/ˈeksɪt ˈmʌltɪpəl/', 'noun', '{"zh-TW":["退出倍數"],"en":["the ratio of final investment value to initial investment at the time of exit"]}', NULL, 'calculate the exit multiple / target exit multiple', '[{"en":"The private equity fund achieved an exit multiple of 3.5 times invested capital.","zh-TW":"私募股權基金實現了3.5倍投入資本的退出倍數。"},{"en":"Exit multiple is a key return metric for private equity investors.","zh-TW":"退出倍數是私募股權投資者的關鍵回報指標。"}]', NULL, NULL, 5, 2591, NULL),
(2592, 'exit strategy', '/ˈɛɡzɪt ˈstrætɪdʒi/', 'noun', '{"zh-TW":["退場策略；出場策略"],"en":["a plan for leaving an investment or business position"]}', NULL, 'develop an exit strategy / execute an exit strategy', '[{"en":"Investors require a clear exit strategy before committing funds.","zh-TW":"投資者在投入資金前需要清晰的退場策略。"},{"en":"The founders planned their exit strategy carefully before selling.","zh-TW":"創辦人在出售前仔細規劃了退場策略。"}]', NULL, NULL, 5, 2592, NULL),
(2593, 'exogenous', '/eksˈɒdʒɪnəs/', 'adjective', '{"zh-TW":["外源性的；外生的"],"en":["originating from outside a system"]}', NULL, 'exogenous shock / exogenous variable / exogenous growth factor', '[{"en":"An oil price spike is an exogenous shock that can derail economic growth.","zh-TW":"油價飆升是一種可能破壞經濟增長的外生衝擊。"},{"en":"The model controls for exogenous factors beyond the firm''s control.","zh-TW":"模型控制了公司無法控制的外生因素。"}]', '{"adverb":"exogenously","antonym":"endogenous"}', NULL, 3, 2593, NULL),
(2594, 'expand', '/ɪkˈspænd/', 'verb', '{"zh-TW":["擴展；擴大"],"en":["to increase in size, number, or importance"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"pand","meaning":"spread (展開)"},"logic":"向外展開，即「擴展」。"}', 'expand operations/business; expand business / expand into new markets', '[{"en":"The company plans to expand into new markets.","zh-TW":"公司計劃擴展到新市場。"},{"en":"We need to expand our product range.","zh-TW":"我們需要擴大產品範圍。"},{"en":"The company plans to expand into Asia.","zh-TW":"公司計畫擴展到亞洲。"},{"en":"We need to expand our product range.","zh-TW":"我們需要擴大產品線。"}]', '{"noun":"expansion","verb":"expand"}', NULL, 2, 2594, 120),
(2595, 'expansion', '/ɪkˈspænʃən/', 'noun', '{"zh-TW":["擴張；擴展"],"en":["the process of increasing in size, scope, or reach"]}', NULL, 'market expansion / business expansion / rapid expansion', '[{"en":"The company is planning expansion into Asian markets.","zh-TW":"公司正計劃向亞洲市場擴張。"},{"en":"Expansion into new territories requires careful planning.","zh-TW":"進入新領域需要仔細規劃。"}]', '{"verb":"expand","adjective":"expanded"}', NULL, 3, 2595, 566),
(2596, 'expansion funding', '/ɪkˈspænʃən ˈfʌndɪŋ/', 'noun', '{"zh-TW":["擴張資金；擴展融資"],"en":["money raised specifically to finance business growth"]}', NULL, 'secure expansion funding / expansion funding round', '[{"en":"The company secured 15 million in expansion funding.","zh-TW":"公司獲得了1500萬元的擴張資金。"},{"en":"Expansion funding was used to open three new regional offices.","zh-TW":"擴張資金用於開設三個新的區域辦公室。"}]', NULL, NULL, 5, 2596, NULL),
(2597, 'expansion plan', '/ɪkˈspænʃən plæn/', 'noun', '{"zh-TW":["擴張計劃"],"en":["a strategy for growing a business into new markets or products"]}', NULL, 'approve an expansion plan / execute an expansion plan', '[{"en":"The board approved a three-year expansion plan into Southeast Asia.","zh-TW":"董事會批准了進入東南亞的三年擴張計劃。"},{"en":"The expansion plan was delayed due to market uncertainty.","zh-TW":"擴張計劃因市場不確定性而延遲了。"}]', NULL, NULL, 5, 2597, NULL),
(2598, 'expatriate', '/ˈekspætriət/', 'noun', '{"zh-TW":["外派員工；海外派駐人員"],"en":["an employee working in a country other than their home country"]}', NULL, 'expatriate assignment / expatriate package / manage expatriates', '[{"en":"The company sent several expatriates to manage the new office.","zh-TW":"公司派遣了幾名外派員工管理新辦公室。"},{"en":"Expatriate packages typically include housing and travel allowances.","zh-TW":"外派員工方案通常包括住房和差旅津貼。"}]', '{"abbreviation":"expat","verb":"expatriate"}', NULL, 4, 2598, NULL),
(2599, 'expect', '/ɪkˈspekt/', 'verb', '{"zh-TW":["期望；預期"],"en":["to believe something will happen"]}', NULL, 'expect + to / be expected to', '[{"en":"We expect revenue to increase next year.","zh-TW":"我們預期明年收入會增加。"},{"en":"Employees are expected to follow the dress code.","zh-TW":"員工被期望遵守服裝規定。"}]', '{"noun":"expectation","verb":"expect","adjective":"expected"}', NULL, 2, 2599, NULL);